-- حقن بيانات CRM — destinations_guide + hotels
-- مُولَّد بواسطة: node scripts/build-crm-injection-sql.mjs
-- نفّذ في Supabase بعد: destinations_guide.sql، hotels.sql، و hotels_category_restructure.sql (إن وُجدت قيم قديمة).
-- الوجهات: 20 دولة؛ المدن: 72؛ الفنادق المقترحة: 288 (4 لكل مدينة).

BEGIN;

DELETE FROM public.hotels WHERE notes LIKE '[Wanderloom seed]%';

ON CONFLICT (country_id, city_id) DO UPDATE SET
  culture = EXCLUDED.culture,
  guidelines = EXCLUDED.guidelines,
  weather_seasons = EXCLUDED.weather_seasons,
  professional_impression = EXCLUDED.professional_impression,
  updated_at = now();


COMMIT;
