INSERT INTO public.destinations_guide (country_id, city_id, culture, guidelines, weather_seasons, professional_impression)
VALUES
('japan', 'tokyo', 'اليابان تُجسّد الاحترام المُتقن (الانحناء، الهدوء في الأماكن العامة، خلع الأحذية عند الأبواب الخشبية) والجمال في التفاصيل الصغيرة. التجربة الفاخرة هنا لا تُباع بصخب، بل بصمتٍ يمنح المسافر إحساساً بأنه ضيفٌ على تقليدٍ عريق. ننصح بتقديم الوجهة كرحلة «إيقاع» وليس سباق معالم.', 'التنقّل: شبكة قطارات شينكانسن فائقة الدقة؛ بطاقة JR Pass تُدرَس حسب مدة الإقامة. العملة: الين الياباني؛ الدفع بالبطاقة منتشر في المدن الكبرى مع إبقاء بعض النقود للأحياء الصغيرة والمعابد. التعامل: الابتعاد عن الصخب في المواصلات، الالتزام بصفوف الانتظار، تجنّب الأكل والمشي في الشوارع المزدحمة حيث يُنظر لها باستياء خفيف.', 'أفضل الشهور: مارس–مايو (موسم الكرز في كثير من المناطق، وطقس معتدل)، وأيضاً أكتوبر–نوفمبر لألوان الخريف في كيوتو. الصيف حار ورطب؛ الشتاء بارد مع أيام صافية مثالية للتصوير. نوّه للعميل بأن «موسم الكرز» يختلف باختلاف خط العرض بين المدن.', 'طوكيو مدينة نيون وانضباط — نقدّمها كقلبٍ نابض يتنفس التقنية والأزياء، مع مساحة للهدوء في حدائق سرّية وشتايات هادئة.'),
('japan', 'osaka', 'اليابان تُجسّد الاحترام المُتقن (الانحناء، الهدوء في الأماكن العامة، خلع الأحذية عند الأبواب الخشبية) والجمال في التفاصيل الصغيرة. التجربة الفاخرة هنا لا تُباع بصخب، بل بصمتٍ يمنح المسافر إحساساً بأنه ضيفٌ على تقليدٍ عريق. ننصح بتقديم الوجهة كرحلة «إيقاع» وليس سباق معالم.', 'التنقّل: شبكة قطارات شينكانسن فائقة الدقة؛ بطاقة JR Pass تُدرَس حسب مدة الإقامة. العملة: الين الياباني؛ الدفع بالبطاقة منتشر في المدن الكبرى مع إبقاء بعض النقود للأحياء الصغيرة والمعابد. التعامل: الابتعاد عن الصخب في المواصلات، الالتزام بصفوف الانتظار، تجنّب الأكل والمشي في الشوارع المزدحمة حيث يُنظر لها باستياء خفيف.', 'أفضل الشهور: مارس–مايو (موسم الكرز في كثير من المناطق، وطقس معتدل)، وأيضاً أكتوبر–نوفمبر لألوان الخريف في كيوتو. الصيف حار ورطب؛ الشتاء بارد مع أيام صافية مثالية للتصوير. نوّه للعميل بأن «موسم الكرز» يختلف باختلاف خط العرض بين المدن.', 'أوساكا مطبخ اليابان الصاخب — الانطباع: دفء بشري ولذّة شارع؛ نصيغها للعميل كتجربة طعمٍ وليلٍ حيٍّ بلا استنفار.'),
('japan', 'kyoto', 'اليابان تُجسّد الاحترام المُتقن (الانحناء، الهدوء في الأماكن العامة، خلع الأحذية عند الأبواب الخشبية) والجمال في التفاصيل الصغيرة. التجربة الفاخرة هنا لا تُباع بصخب، بل بصمتٍ يمنح المسافر إحساساً بأنه ضيفٌ على تقليدٍ عريق. ننصح بتقديم الوجهة كرحلة «إيقاع» وليس سباق معالم.', 'التنقّل: شبكة قطارات شينكانسن فائقة الدقة؛ بطاقة JR Pass تُدرَس حسب مدة الإقامة. العملة: الين الياباني؛ الدفع بالبطاقة منتشر في المدن الكبرى مع إبقاء بعض النقود للأحياء الصغيرة والمعابد. التعامل: الابتعاد عن الصخب في المواصلات، الالتزام بصفوف الانتظار، تجنّب الأكل والمشي في الشوارع المزدحمة حيث يُنظر لها باستياء خفيف.', 'أفضل الشهور: مارس–مايو (موسم الكرز في كثير من المناطق، وطقس معتدل)، وأيضاً أكتوبر–نوفمبر لألوان الخريف في كيوتو. الصيف حار ورطب؛ الشتاء بارد مع أيام صافية مثالية للتصوير. نوّه للعميل بأن «موسم الكرز» يختلف باختلاف خط العرض بين المدن.', 'كيوتو روح اليابان الخشبية — نبيع «الانتقال الزمني»: معابد، مسارات بامبو، وريوكان يختصر أوموتيناشي.'),
('korea', 'seoul', 'كوريا تجمع بين الطاقة الحضرية الخارقة والاحترام للتسلسل الاجتماعي واللباس المحتشم في السياقات التقليدية. الطعام طقسٌ اجتماعي: المشاركة، والباربكيو الكوري، والبانشان جزء من الهوية. للعميل الفاخر: نبرة «مدينة المستقبل» مع روح حارة تحت السطح.', 'التنقّل: مترو أنظف وسريع في سيول وبوسان؛ تطبيقات التاكسي والتأجير شائعة. العملة: الوون؛ البطاقات منتشرة. التعامل: الإطراء بمستوى منخفض من الصوت، تقديم البطاقة بيدين عند التعارف في سياقات العمل.', 'الربيع (أبريل–مايو) مثالي للزهور والمشي؛ الخريف (سبتمبر–أكتوبر) صافٍ ومنعش. الصيف رطب؛ الشتاء بارد وجاف في سيول. جيجو أكثر اعتدالاً مع رياح بحرية.', 'سيول تلتقي فيها الكي بوب والقصور — نبرة فاخرة: مدينة مستقبلية بذاكرة ملكية، مع مساحات للتسوق الراقي والفن.'),
('korea', 'busan', 'كوريا تجمع بين الطاقة الحضرية الخارقة والاحترام للتسلسل الاجتماعي واللباس المحتشم في السياقات التقليدية. الطعام طقسٌ اجتماعي: المشاركة، والباربكيو الكوري، والبانشان جزء من الهوية. للعميل الفاخر: نبرة «مدينة المستقبل» مع روح حارة تحت السطح.', 'التنقّل: مترو أنظف وسريع في سيول وبوسان؛ تطبيقات التاكسي والتأجير شائعة. العملة: الوون؛ البطاقات منتشرة. التعامل: الإطراء بمستوى منخفض من الصوت، تقديم البطاقة بيدين عند التعارف في سياقات العمل.', 'الربيع (أبريل–مايو) مثالي للزهور والمشي؛ الخريف (سبتمبر–أكتوبر) صافٍ ومنعش. الصيف رطب؛ الشتاء بارد وجاف في سيول. جيجو أكثر اعتدالاً مع رياح بحرية.', 'بوسان بحر وجسر — انطباق بحري أنيق؛ نقدّمها كوجهة مأكولات بحرية وأسواق ليلية بإيقاع لطيف.'),
('korea', 'jeju', 'كوريا تجمع بين الطاقة الحضرية الخارقة والاحترام للتسلسل الاجتماعي واللباس المحتشم في السياقات التقليدية. الطعام طقسٌ اجتماعي: المشاركة، والباربكيو الكوري، والبانشان جزء من الهوية. للعميل الفاخر: نبرة «مدينة المستقبل» مع روح حارة تحت السطح.', 'التنقّل: مترو أنظف وسريع في سيول وبوسان؛ تطبيقات التاكسي والتأجير شائعة. العملة: الوون؛ البطاقات منتشرة. التعامل: الإطراء بمستوى منخفض من الصوت، تقديم البطاقة بيدين عند التعارف في سياقات العمل.', 'الربيع (أبريل–مايو) مثالي للزهور والمشي؛ الخريف (سبتمبر–أكتوبر) صافٍ ومنعش. الصيف رطب؛ الشتاء بارد وجاف في سيول. جيجو أكثر اعتدالاً مع رياح بحرية.', 'جيجو جزيرة بركان وهدوء — فخامة «طبيعة وخصوصية»؛ مثالية لمن يبحث عن إبطاء إيقاع الرحلة.'),
('portugal', 'lisbon', 'البرتغال تُروى بلغة «سوداد» — شوقٌ لطيف يميل للشاعرية. الفخامة هنا دافئة وليست صارمة: البلاط الملون، الفوندو، الموسيقى الفادو في لشبونة، والانحدار نحو نهر دوور في بورتو. نقدّم الوجهة كحكاية بشرية لا ككتالوج معالم.', 'التنقّل: قطارات مريحة بين المدن؛ الترام في لشبونة شديد الانحدار — أحذية مريحة ضرورية. العملة: اليورو. التعامل: البرتغاليون ودودون؛ الإنجليزية منتشرة في القطاع السياحي.', 'أبريل–يونيو وسبتمبر–أكتوبر مثالية (دافئ دون حرّ قاتل). يوليو–أغسطس مزدحم على السواحل. الشتاء معتدل في الجنوب مع أمطار في الشمال.', 'لشبونة تلال وترام وفادو — نبيع غروباً يلامس البلاط، مع نصيحة أزقة ألفاما والبرتغال الدافئ.'),
('portugal', 'porto', 'البرتغال تُروى بلغة «سوداد» — شوقٌ لطيف يميل للشاعرية. الفخامة هنا دافئة وليست صارمة: البلاط الملون، الفوندو، الموسيقى الفادو في لشبونة، والانحدار نحو نهر دوور في بورتو. نقدّم الوجهة كحكاية بشرية لا ككتالوج معالم.', 'التنقّل: قطارات مريحة بين المدن؛ الترام في لشبونة شديد الانحدار — أحذية مريحة ضرورية. العملة: اليورو. التعامل: البرتغاليون ودودون؛ الإنجليزية منتشرة في القطاع السياحي.', 'أبريل–يونيو وسبتمبر–أكتوبر مثالية (دافئ دون حرّ قاتل). يوليو–أغسطس مزدحم على السواحل. الشتاء معتدل في الجنوب مع أمطار في الشمال.', 'بورتو نهر وعناقين أزرق — انطباع: نبيذ، جسور، ومدينة أصيلة؛ نربطها بتجربة ضيافة نهرية هادئة.'),
('portugal', 'algarve', 'البرتغال تُروى بلغة «سوداد» — شوقٌ لطيف يميل للشاعرية. الفخامة هنا دافئة وليست صارمة: البلاط الملون، الفوندو، الموسيقى الفادو في لشبونة، والانحدار نحو نهر دوور في بورتو. نقدّم الوجهة كحكاية بشرية لا ككتالوج معالم.', 'التنقّل: قطارات مريحة بين المدن؛ الترام في لشبونة شديد الانحدار — أحذية مريحة ضرورية. العملة: اليورو. التعامل: البرتغاليون ودودون؛ الإنجليزية منتشرة في القطاع السياحي.', 'أبريل–يونيو وسبتمبر–أكتوبر مثالية (دافئ دون حرّ قاتل). يوليو–أغسطس مزدحم على السواحل. الشتاء معتدل في الجنوب مع أمطار في الشمال.', 'الغارف منحدرات وبحر كهرماني — نقدّمها كاستراحة شمسية أنيقة بين الجولف والكوفات الصخرية.'),
('italy', 'rome', 'إيطاليا «لا دولتش فيتا» الممزوجة بالعمق التاريخي: الوجبة امتداد لليوم، والمقهى فاصلة، والكنيسة أو الساحة ذروة معنوية. الفخامة الإيطالية صاخبة أحياناً — ألوان، نكهات، ومشاعر صريحة.', 'التنقّل: قطارات فريتشيا رابطة بين المدن الكبرى؛ داخل المدن المشي والتأجير المحدود للسيارات في الريف. العملة: اليورو. التعامل: تحية بسيطة، احترام أوقات الراحة بعد الظهر في أحياء تقليدية.', 'أبريل–يونيو وسبتمبر–أكتوبر مثالية لمعظم المدن. الصيف حار جداً في روما وفلورنسا؛ الساحل والجزر أكثر راحة. الشتاء ألطف في الجنوب.', 'روما لا تُروى في يوم — نبيع «الأبدية»: ممرّات، نوافير، ومطابخ تُحترم فيها الوقت.'),
('italy', 'florence', 'إيطاليا «لا دولتش فيتا» الممزوجة بالعمق التاريخي: الوجبة امتداد لليوم، والمقهى فاصلة، والكنيسة أو الساحة ذروة معنوية. الفخامة الإيطالية صاخبة أحياناً — ألوان، نكهات، ومشاعر صريحة.', 'التنقّل: قطارات فريتشيا رابطة بين المدن الكبرى؛ داخل المدن المشي والتأجير المحدود للسيارات في الريف. العملة: اليورو. التعامل: تحية بسيطة، احترام أوقات الراحة بعد الظهر في أحياء تقليدية.', 'أبريل–يونيو وسبتمبر–أكتوبر مثالية لمعظم المدن. الصيف حار جداً في روما وفلورنسا؛ الساحل والجزر أكثر راحة. الشتاء ألطف في الجنوب.', 'فلورنسا رنيسانسٌ حيٌّ في كل زاوية — انطباع: زيتون، جلد، ومتاحف تتنفس؛ نربطها بتذوّق بطيء.'),
('italy', 'venice', 'إيطاليا «لا دولتش فيتا» الممزوجة بالعمق التاريخي: الوجبة امتداد لليوم، والمقهى فاصلة، والكنيسة أو الساحة ذروة معنوية. الفخامة الإيطالية صاخبة أحياناً — ألوان، نكهات، ومشاعر صريحة.', 'التنقّل: قطارات فريتشيا رابطة بين المدن الكبرى؛ داخل المدن المشي والتأجير المحدود للسيارات في الريف. العملة: اليورو. التعامل: تحية بسيطة، احترام أوقات الراحة بعد الظهر في أحياء تقليدية.', 'أبريل–يونيو وسبتمبر–أكتوبر مثالية لمعظم المدن. الصيف حار جداً في روما وفلورنسا؛ الساحل والجزر أكثر راحة. الشتاء ألطف في الجنوب.', 'البندقية ماءً وضوءاً — فخامة «جندول وهدوء»؛ نحذّر من الزحام ونقترح توقيتاً ذهبياً للعميل.'),
('italy', 'milan', 'إيطاليا «لا دولتش فيتا» الممزوجة بالعمق التاريخي: الوجبة امتداد لليوم، والمقهى فاصلة، والكنيسة أو الساحة ذروة معنوية. الفخامة الإيطالية صاخبة أحياناً — ألوان، نكهات، ومشاعر صريحة.', 'التنقّل: قطارات فريتشيا رابطة بين المدن الكبرى؛ داخل المدن المشي والتأجير المحدود للسيارات في الريف. العملة: اليورو. التعامل: تحية بسيطة، احترام أوقات الراحة بعد الظهر في أحياء تقليدية.', 'أبريل–يونيو وسبتمبر–أكتوبر مثالية لمعظم المدن. الصيف حار جداً في روما وفلورنسا؛ الساحل والجزر أكثر راحة. الشتاء ألطف في الجنوب.', 'ميلانو أزياء وتصميم — نبرة عصرية فاخرة؛ نربطها بعروض، ديكور، ومطبخ شمالي أنيق.'),
('italy', 'naples', 'إيطاليا «لا دولتش فيتا» الممزوجة بالعمق التاريخي: الوجبة امتداد لليوم، والمقهى فاصلة، والكنيسة أو الساحة ذروة معنوية. الفخامة الإيطالية صاخبة أحياناً — ألوان، نكهات، ومشاعر صريحة.', 'التنقّل: قطارات فريتشيا رابطة بين المدن الكبرى؛ داخل المدن المشي والتأجير المحدود للسيارات في الريف. العملة: اليورو. التعامل: تحية بسيطة، احترام أوقات الراحة بعد الظهر في أحياء تقليدية.', 'أبريل–يونيو وسبتمبر–أكتوبر مثالية لمعظم المدن. الصيف حار جداً في روما وفلورنسا؛ الساحل والجزر أكثر راحة. الشتاء ألطف في الجنوب.', 'نابولي نابولي حقيقية — بيتزا، خليج، وبوابة جنوب؛ نقدّمها بحماسٍ أصيل مع لمسة فندقية هادئة للراحة.'),
('france', 'paris', 'فرنسا تُعبّر عن الأناقة كأسلوب حياة: المطبخ، اللغة، الفن، والحديقة أو الواجهة المقوسة. الفخامة الفرنسية غالباً «هادئة» — جودة خامات وتوقيت مثالي أكثر من البهرجة.', 'التنقّل: TGV بين المدن؛ في باريس مترو وRER؛ تجنّب قيادة داخل الأحياء الضيقة إن أمكن. العملة: اليورو. التعامل: التحية بالفرنسية مقدّرة؛ احترام أوقات الوجبات في المطاعم الراقية.', 'الربيع مبكراً في الجنوب (نيس)؛ باريس رائعة في مايو–يونيو وأيلول. ديسمبر–يناير: أضواء وأجواء شتوية أنيقة. الصيف في الجنوب حار ومزدحم على البحر.', 'باريس فن وحياة — نبيع «اللحظة الأنيقة»: مقهى، جسر، ومتحف بلا إرهاق برنامج.'),
('france', 'nice', 'فرنسا تُعبّر عن الأناقة كأسلوب حياة: المطبخ، اللغة، الفن، والحديقة أو الواجهة المقوسة. الفخامة الفرنسية غالباً «هادئة» — جودة خامات وتوقيت مثالي أكثر من البهرجة.', 'التنقّل: TGV بين المدن؛ في باريس مترو وRER؛ تجنّب قيادة داخل الأحياء الضيقة إن أمكن. العملة: اليورو. التعامل: التحية بالفرنسية مقدّرة؛ احترام أوقات الوجبات في المطاعم الراقية.', 'الربيع مبكراً في الجنوب (نيس)؛ باريس رائعة في مايو–يونيو وأيلول. ديسمبر–يناير: أضواء وأجواء شتوية أنيقة. الصيف في الجنوب حار ومزدحم على البحر.', 'نيس كوت دازور — انطباع: بحر متوسطي بهدوء فرنسي؛ نربطها بمشي الواجهة ووجبات طويلة.'),
